  "vitals.interpretation.bp.typical.details": "यह रीडिंग वयस्कों के लिए सामान्यतः स्वस्थ मानी जाने वाली सीमा में है।",
  "vitals.interpretation.bp.slight.title": "थोड़ा बढ़ा हुआ",
  "vitals.interpretation.bp.slight.details": "यह सामान्य सीमा से थोड़ा अधिक है। ऐसी रीडिंग कभी-कभी सामान्य होती हैं, लेकिन समय के साथ इस पर नज़र रखना उचित है।",
  "vitals.interpretation.bp.elevated.title": "बढ़ा हुआ",
  "vitals.interpretation.bp.elevated.details": "यह रीडिंग सामान्य से अधिक है। अपने अगले क्लिनिशियन विज़िट में इस रुझान का उल्लेख करने पर विचार करें।",
  "vitals.interpretation.bp.high.title": "उच्च",
  "vitals.interpretation.bp.high.details": "यह रीडिंग सामान्य सीमा से काफी अधिक है। कृपया इसे अपने क्लिनिशियन के साथ साझा करें, खासकर यदि यह दोहराए।",
  "vitals.interpretation.hr.low.title": "सामान्य से कम",
  "vitals.interpretation.hr.low.details": "इस सीमा से कम विश्राम हृदय गति कुछ लोगों के लिए सामान्य हो सकती है, खासकर यदि वे सक्रिय या एथलेटिक हों, लेकिन यदि अस्वस्थ महसूस हो तो इसका उल्लेख करें।",
  "vitals.interpretation.hr.typical.title": "सामान्य सीमा में",
  "vitals.interpretation.hr.typical.details": "यह विश्राम हृदय गति वयस्कों के लिए सामान्यतः स्वस्थ मानी जाने वाली सीमा में है।",
  "vitals.interpretation.hr.high.title": "सामान्य से अधिक",
  "vitals.interpretation.hr.high.details": "यह सामान्य विश्राम सीमा से अधिक है। यदि यह बना रहे या लक्षणों के साथ हो, तो अपने क्लिनिशियन से जांच कराएं।",
  "vitals.interpretation.o2.reassuring.title": "संतोषजनक",
  "vitals.interpretation.o2.reassuring.details": "यह ऑक्सीजन सैचुरेशन रीडिंग सामान्यतः स्वस्थ मानी जाने वाली सीमा में है।",
  "vitals.interpretation.o2.low.title": "सामान्य से कम",
  "vitals.interpretation.o2.low.details": "यह रीडिंग सामान्य सीमा से कम है। यदि आपको सांस लेने में तकलीफ महसूस हो रही है, तो कृपया तुरंत चिकित्सा सहायता लें।",
  "vitals.interpretation.temp.typical.title": "सामान्य",
  "vitals.interpretation.temp.typical.details": "यह तापमान रीडिंग सामान्यतः स्वस्थ मानी जाने वाली सीमा में है।",
  "vitals.interpretation.temp.high.title": "बुखार की सीमा",
  "vitals.interpretation.temp.high.details": "यह रीडिंग बुखार का संकेत देती है। आराम, तरल पदार्थ और निगरानी की सामान्यतः सलाह दी जाती है — यदि यह बना रहे या गंभीर हो तो अपने क्लिनिशियन से संपर्क करें।",
  "vitals.interpretation.temp.outside.title": "सामान्य सीमा से बाहर",
  "vitals.interpretation.temp.outside.details": "यह रीडिंग सामान्यतः स्वस्थ मानी जाने वाली सीमा से बाहर है। दोबारा माप लेने पर विचार करें, और यदि यह जारी रहे तो अपने क्लिनिशियन को बताएं।",
  "vitals.interpretation.weight.title": "वज़न दर्ज किया गया",
  "vitals.interpretation.weight.details": "समय के साथ वज़न पर नज़र रखने से आपको और आपके क्लिनिशियन को चर्चा योग्य रुझान पहचानने में मदद मिल सकती है।",
  "vitals.interpretation.glucose.title": "ग्लूकोज़ दर्ज किया गया",
  "vitals.interpretation.glucose.details": "समय के साथ ग्लूकोज़ पर नज़र रखने से आपको और आपके क्लिनिशियन को चर्चा योग्य रुझान पहचानने में मदद मिल सकती है।",
