  "vitals.interpretation.bp.typical.title": "স্বাভাবিক পরিসরে",
  "vitals.interpretation.bp.typical.details": "এই রিডিং প্রাপ্তবয়স্কদের জন্য সাধারণত সুস্থ পরিসরের মধ্যে পড়ে।",
  "vitals.interpretation.bp.slight.title": "সামান্য বৃদ্ধি",
  "vitals.interpretation.bp.slight.details": "এটি স্বাভাবিক পরিসরের চেয়ে সামান্য বেশি। এই ধরনের রিডিং মাঝে মাঝে সাধারণ, তবে সময়ের সাথে ট্র্যাক করা ভালো।",
  "vitals.interpretation.bp.elevated.title": "উচ্চতর",
  "vitals.interpretation.bp.elevated.details": "এই রিডিং স্বাভাবিকের চেয়ে বেশি। আপনার পরবর্তী ক্লিনিশিয়ান ভিজিটে এই প্রবণতা উল্লেখ করার কথা বিবেচনা করুন।",
  "vitals.interpretation.bp.high.title": "উচ্চ",
  "vitals.interpretation.bp.high.details": "এই রিডিং স্বাভাবিক পরিসরের চেয়ে উল্লেখযোগ্যভাবে বেশি। এটি আপনার ক্লিনিশিয়ানের সাথে শেয়ার করুন, বিশেষত যদি এটি পুনরাবৃত্তি হয়।",
  "vitals.interpretation.hr.low.title": "স্বাভাবিকের চেয়ে কম",
  "vitals.interpretation.hr.low.details": "এই পরিসরের নিচে বিশ্রামরত হৃদস্পন্দন কারো কারো জন্য স্বাভাবিক হতে পারে, বিশেষত সক্রিয় বা ক্রীড়াবিদ হলে, তবে অসুস্থ বোধ করলে উল্লেখ করুন।",
  "vitals.interpretation.hr.typical.title": "স্বাভাবিক পরিসরে",
  "vitals.interpretation.hr.typical.details": "এই বিশ্রামরত হৃদস্পন্দন প্রাপ্তবয়স্কদের জন্য সাধারণত সুস্থ পরিসরের মধ্যে পড়ে।",
  "vitals.interpretation.hr.high.title": "স্বাভাবিকের চেয়ে বেশি",
  "vitals.interpretation.hr.high.details": "এটি স্বাভাবিক বিশ্রামের পরিসরের চেয়ে বেশি। যদি এটি অব্যাহত থাকে বা উপসর্গের সাথে থাকে, আপনার ক্লিনিশিয়ানের সাথে যোগাযোগ করুন।",
  "vitals.interpretation.o2.reassuring.title": "স্বস্তিদায়ক",
  "vitals.interpretation.o2.reassuring.details": "এই অক্সিজেন স্যাচুরেশন রিডিং সাধারণত সুস্থ পরিসরের মধ্যে।",
  "vitals.interpretation.o2.low.title": "স্বাভাবিকের চেয়ে কম",
  "vitals.interpretation.o2.low.details": "এই রিডিং স্বাভাবিক পরিসরের চেয়ে কম। যদি আপনার শ্বাসকষ্ট হয়, দয়া করে অবিলম্বে চিকিৎসা সহায়তা নিন।",
  "vitals.interpretation.temp.typical.title": "স্বাভাবিক",
  "vitals.interpretation.temp.typical.details": "এই তাপমাত্রা রিডিং সাধারণত স্বাভাবিক পরিসরের মধ্যে।",
  "vitals.interpretation.temp.high.title": "জ্বরের পরিসর",
  "vitals.interpretation.temp.high.details": "এই রিডিং জ্বর নির্দেশ করে। বিশ্রাম, তরল এবং পর্যবেক্ষণ সাধারণত পরামর্শ দেওয়া হয় — এটি অব্যাহত থাকলে বা গুরুতর হলে আপনার ক্লিনিশিয়ানের সাথে যোগাযোগ করুন।",
  "vitals.interpretation.temp.outside.title": "স্বাভাবিক পরিসরের বাইরে",
  "vitals.interpretation.temp.outside.details": "এই রিডিং সাধারণত স্বাভাবিক পরিসরের বাইরে পড়ে। পুনরায় পরিমাপ করার কথা বিবেচনা করুন, এবং এটি অব্যাহত থাকলে আপনার ক্লিনিশিয়ানকে জানান।",
  "vitals.interpretation.weight.title": "ওজন লগ করা হয়েছে",
  "vitals.interpretation.weight.details": "সময়ের সাথে ওজন ট্র্যাক করা আপনাকে এবং আপনার ক্লিনিশিয়ানকে আলোচনাযোগ্য প্রবণতা চিহ্নিত করতে সাহায্য করতে পারে।",
  "vitals.interpretation.glucose.title": "গ্লুকোজ লগ করা হয়েছে",
  "vitals.interpretation.glucose.details": "সময়ের সাথে গ্লুকোজ ট্র্যাক করা আপনাকে এবং আপনার ক্লিনিশিয়ানকে আলোচনাযোগ্য প্রবণতা চিহ্নিত করতে সাহায্য করতে পারে।",
