    "vitals.sources.futureNote": "ಮುಖ್ಯ ಹಸ್ತಚಾಲಿತ-ವೈಟಲ್ಸ್ ಪೈಪ್‌ಲೈನ್ ಸ್ಥಿರವಾದ ನಂತರ ಸಂಪರ್ಕಿತ-ಮೂಲ ಅಧಿಕಾರೀಕರಣ ಮತ್ತು ಪೂರೈಕೆದಾರ-ನಿರ್ದಿಷ್ಟ ಇಂಜೆಸ್ಚನ್ ಸೇರಿಸಲಾಗುವುದು.",
