    "vitals.history.description": "ಪ್ರತಿ ರೀಡಿಂಗ್ ತನ್ನ ಮೂಲ ಮತ್ತು ಸಮಯಮುದ್ರೆಯನ್ನು ಉಳಿಸಿಕೊಳ್ಳುತ್ತದೆ.",
    "vitals.history.noneTitle": "ಯಾವುದೇ ಮಾಪನಗಳು ಕಂಡುಬಂದಿಲ್ಲ",
    "vitals.history.noneDescription": "ಮೇಲೆ ನಿಮ್ಮ ಮೊದಲ ರೀಡಿಂಗ್ ಸೇರಿಸಿ.",
    "vitals.deviceLabel": "ಸಾಧನ:",
    "vitals.recorded": "ದಾಖಲಿಸಲಾಗಿದೆ",
    "vitals.interpretation.measurementUnavailable.title": "ಇನ್ನೂ ರೀಡಿಂಗ್ ಇಲ್ಲ",
    "vitals.interpretation.measurementUnavailable.summary": "ಇಲ್ಲಿ ವಿವರಣೆಯನ್ನು ನೋಡಲು ಮಾಪನವನ್ನು ಸೇರಿಸಿ.",
    "vitals.interpretation.measurementUnavailable.details": "ನೀವು ಒಂದು ರೀಡಿಂಗ್ ದಾಖಲಿಸಿದ ನಂತರ, JeevanLink ಅದರ ಸಾಮಾನ್ಯ ಅರ್ಥವನ್ನು ಸಾರಾಂಶಗೊಳಿಸುತ್ತದೆ — ರೋಗನಿರ್ಣಯವಾಗಿ ಅಲ್ಲ, ಒಂದು ಅವಲೋಕನವಾಗಿ.",
    "vitals.interpretation.bp.low.title": "ಸಾಮಾನ್ಯಕ್ಕಿಂತ ಕಡಿಮೆ",
    "vitals.interpretation.bp.low.details": "ಈ ರೀಡಿಂಗ್ ಸಾಮಾನ್ಯ ವ್ಯಾಪ್ತಿಗಿಂತ ಕಡಿಮೆಯಿದೆ. ನಿಮಗೆ ತಲೆಸುತ್ತು, ಮೂರ್ಛೆ ಅಥವಾ ಅಸ್ವಸ್ಥತೆ ಅನಿಸಿದರೆ, ನಿಮ್ಮ ಕ್ಲಿನಿಷಿಯನ್ ಅನ್ನು ಸಂಪರ್ಕಿಸಿ.",
    "vitals.interpretation.bp.typical.title": "ಸಾಮಾನ್ಯ ವ್ಯಾಪ್ತಿಯಲ್ಲಿ",
    "vitals.interpretation.bp.typical.details": "ಈ ರೀಡಿಂಗ್ ವಯಸ್ಕರಿಗೆ ಸಾಮಾನ್ಯವಾಗಿ ವರದಿ ಮಾಡಲಾದ ಆರೋಗ್ಯಕರ ವ್ಯಾಪ್ತಿಯಲ್ಲಿ ಬರುತ್ತದೆ.",
    "vitals.interpretation.bp.slight.title": "ಸ್ವಲ್ಪ ಹೆಚ್ಚಾಗಿದೆ",
    "vitals.interpretation.bp.slight.details": "ಇದು ಸಾಮಾನ್ಯ ವ್ಯಾಪ್ತಿಗಿಂತ ಸ್ವಲ್ಪ ಹೆಚ್ಚಾಗಿದೆ. ಇಂತಹ ಸಾಂದರ್ಭಿಕ ರೀಡಿಂಗ್‌ಗಳು ಸಾಮಾನ್ಯ, ಆದರೆ ಕಾಲಾನಂತರದಲ್ಲಿ ಟ್ರ್ಯಾಕ್ ಮಾಡುವುದು ಯೋಗ್ಯ.",
    "vitals.interpretation.bp.elevated.title": "ಹೆಚ್ಚಾಗಿದೆ",
    "vitals.interpretation.bp.elevated.details": "ಈ ರೀಡಿಂಗ್ ಸಾಮಾನ್ಯಕ್ಕಿಂತ ಹೆಚ್ಚಾಗಿದೆ. ನಿಮ್ಮ ಮುಂದಿನ ಕ್ಲಿನಿಷಿಯನ್ ಭೇಟಿಯಲ್ಲಿ ಈ ಪ್ರವೃತ್ತಿಯನ್ನು ಉಲ್ಲೇಖಿಸುವುದನ್ನು ಪರಿಗಣಿಸಿ.",
    "vitals.interpretation.bp.high.title": "ಅಧಿಕ",
    "vitals.interpretation.bp.high.details": "ಈ ರೀಡಿಂಗ್ ಸಾಮಾನ್ಯ ವ್ಯಾಪ್ತಿಗಿಂತ ಗಣನೀಯವಾಗಿ ಹೆಚ್ಚಾಗಿದೆ. ದಯವಿಟ್ಟು ಇದನ್ನು ನಿಮ್ಮ ಕ್ಲಿನಿಷಿಯನ್ ಜೊತೆ ಹಂಚಿಕೊಳ್ಳಿ, ವಿಶೇಷವಾಗಿ ಇದು ಪುನರಾವರ್ತಿಸಿದರೆ.",
    "vitals.interpretation.hr.low.title": "ಸಾಮಾನ್ಯಕ್ಕಿಂತ ಕಡಿಮೆ",
    "vitals.interpretation.hr.low.details": "ಈ ವ್ಯಾಪ್ತಿಗಿಂತ ಕಡಿಮೆ ವಿಶ್ರಾಂತಿ ಹೃದಯ ಬಡಿತ ದರಗಳು ಕೆಲವರಿಗೆ ಸಾಮಾನ್ಯವಾಗಿರಬಹುದು, ವಿಶೇಷವಾಗಿ ಸಕ್ರಿಯ ಅಥವಾ ಕ್ರೀಡಾಪಟುವಾಗಿದ್ದರೆ, ಆದರೆ ಅಸ್ವಸ್ಥತೆ ಅನಿಸಿದರೆ ಉಲ್ಲೇಖಿಸಿ.",
    "vitals.interpretation.hr.typical.title": "ಸಾಮಾನ್ಯ ವ್ಯಾಪ್ತಿಯಲ್ಲಿ",
    "vitals.interpretation.hr.typical.details": "ಈ ವಿಶ್ರಾಂತಿ ಹೃದಯ ಬಡಿತ ದರ ವಯಸ್ಕರಿಗೆ ಸಾಮಾನ್ಯವಾಗಿ ವರದಿ ಮಾಡಲಾದ ಆರೋಗ್ಯಕರ ವ್ಯಾಪ್ತಿಯಲ್ಲಿ ಬರುತ್ತದೆ.",
    "vitals.interpretation.hr.high.title": "ಸಾಮಾನ್ಯಕ್ಕಿಂತ ಹೆಚ್ಚು",
    "vitals.interpretation.hr.high.details": "ಇದು ಸಾಮಾನ್ಯ ವಿಶ್ರಾಂತಿ ವ್ಯಾಪ್ತಿಗಿಂತ ಹೆಚ್ಚಾಗಿದೆ. ಇದು ಮುಂದುವರಿದರೆ ಅಥವಾ ಲಕ್ಷಣಗಳೊಂದಿಗೆ ಬಂದರೆ, ನಿಮ್ಮ ಕ್ಲಿನಿಷಿಯನ್ ಜೊತೆ ಪರಿಶೀಲಿಸಿ.",
    "vitals.interpretation.o2.reassuring.title": "ಭರವಸೆದಾಯಕ",
    "vitals.interpretation.o2.reassuring.details": "ಈ ಆಮ್ಲಜನಕ ಸಾಚುರೇಶನ್ ರೀಡಿಂಗ್ ಸಾಮಾನ್ಯವಾಗಿ ವರದಿ ಮಾಡಲಾದ ಆರೋಗ್ಯಕರ ವ್ಯಾಪ್ತಿಯಲ್ಲಿದೆ.",
    "vitals.interpretation.o2.low.title": "ಸಾಮಾನ್ಯಕ್ಕಿಂತ ಕಡಿಮೆ",
    "vitals.interpretation.o2.low.details": "ಈ ರೀಡಿಂಗ್ ಸಾಮಾನ್ಯ ವ್ಯಾಪ್ತಿಗಿಂತ ಕಡಿಮೆಯಿದೆ. ನಿಮಗೆ ಉಸಿರಾಟದ ತೊಂದರೆ ಅನುಭವಿಸುತ್ತಿದ್ದರೆ, ದಯವಿಟ್ಟು ವೈದ್ಯಕೀಯ ನೆರವು ಪಡೆಯಿರಿ.",
    "vitals.interpretation.temp.typical.title": "ಸಾಮಾನ್ಯ",
    "vitals.interpretation.temp.typical.details": "ಈ ತಾಪಮಾನ ರೀಡಿಂಗ್ ಸಾಮಾನ್ಯವಾಗಿ ವರದಿ ಮಾಡಲಾದ ಸಾಮಾನ್ಯ ವ್ಯಾಪ್ತಿಯಲ್ಲಿದೆ.",
    "vitals.interpretation.temp.high.title": "ಜ್ವರ ವ್ಯಾಪ್ತಿ",
    "vitals.interpretation.temp.high.details": "ಈ ರೀಡಿಂಗ್ ಜ್ವರವನ್ನು ಸೂಚಿಸುತ್ತದೆ. ವಿಶ್ರಾಂತಿ, ದ್ರವಗಳು ಮತ್ತು ಮೇಲ್ವಿಚಾರಣೆಯನ್ನು ಸಾಮಾನ್ಯವಾಗಿ ಸಲಹೆ ನೀಡಲಾಗುತ್ತದೆ — ಇದು ಮುಂದುವರಿದರೆ ಅಥವಾ ತೀವ್ರವಾಗಿದ್ದರೆ ನಿಮ್ಮ ಕ್ಲಿನಿಷಿಯನ್ ಅನ್ನು ಸಂಪರ್ಕಿಸಿ.",
    "vitals.interpretation.temp.outside.title": "ಸಾಮಾನ್ಯ ವ್ಯಾಪ್ತಿಯ ಹೊರಗೆ",
