    "scribe.subtitle": "നിങ്ങളുടെ കൺസൾട്ടേഷൻ കുറിപ്പുകൾ പറയുകയോ ടൈപ്പ് ചെയ്യുകയോ ചെയ്യുക. AI അവയെ അവലോകനത്തിനും തിരുത്തലിനുമായി SOAP-ഫോർമാറ്റ് കരടായി ക്രമീകരിക്കുന്നു — നിങ്ങൾ അംഗീകരിക്കുന്നതുവരെ രോഗിയുടെ രേഖയിൽ ഒന്നും സംരക്ഷിക്കില്ല.",
