    "scribe.notesPlaceholder": "ഉദാഹരണം: രോഗി മൂന്ന് ദിവസമായി വരണ്ട ചുമയും നേരിയ പനിയും റിപ്പോർട്ട് ചെയ്യുന്നു, രാത്രി കൂടുതൽ വഷളാകുന്നു. ശ്വാസതടസ്സമില്ല. പരിശോധനയിൽ നെഞ്ച് വ്യക്തം, താപനില 99.8F. വൈറൽ URI ആകാം. വിശ്രമം, ദ്രാവകങ്ങൾ, ആവശ്യമെങ്കിൽ പാരാസെറ്റമോൾ നിർദ്ദേശിച്ചു, 5 ദിവസത്തിനുള്ളിൽ മെച്ചപ്പെടുന്നില്ലെങ്കിൽ അവലോകനം ചെയ്യുക.",
