    "scribe.subtitle": "ଆପଣଙ୍କ ପରାମର୍ଶ ଟିପ୍ପଣୀ କୁହନ୍ତୁ କିମ୍ବା ଟାଇପ୍ କରନ୍ତୁ। AI ସେଗୁଡ଼ିକୁ ସମୀକ୍ଷା ଏବଂ ସମ୍ପାଦନା ପାଇଁ SOAP-ଫର୍ମାଟ୍ ଡ୍ରାଫ୍ଟରେ ସଜାଏ — ଆପଣ ଅନୁମୋଦନ ନକରିବା ପର୍ଯ୍ୟନ୍ତ ରୋଗୀଙ୍କ ରେକର୍ଡରେ କିଛି ସେଭ୍ ହୁଏ ନାହିଁ।",
