    "scribe.stop": "ବନ୍ଦ କରନ୍ତୁ",
    "scribe.transcribing": "ପ୍ରତିଲିପି ହେଉଛି…",
    "scribe.dictate": "କହି ଲେଖାନ୍ତୁ",
    "scribe.notesPlaceholder": "ଉଦାହରଣ: ରୋଗୀ ତିନି ଦିନ ଧରି ଶୁଷ୍କ କାଶ ଏବଂ ହାଲୁକା ଜ୍ୱର ଅଭିଯୋଗ କରିଛନ୍ତି, ରାତିରେ ଅଧିକ ଖରାପ ହୁଏ। ନିଶ୍ୱାସ ନେବାରେ ଅସୁବିଧା ନାହିଁ। ପରୀକ୍ଷାରେ ଛାତି ସଫା, ତାପମାତ୍ରା 99.8F। ସମ୍ଭବତଃ ଭାଇରାଲ୍ URI। ବିଶ୍ରାମ, ତରଳ ପଦାର୍ଥ, ଆବଶ୍ୟକ ଅନୁଯାୟୀ ପାରାସିଟାମଲ୍ ପରାମର୍ଶ ଦିଆଗଲା, 5 ଦିନରେ ଉନ୍ନତି ନହେଲେ ସମୀକ୍ଷା କରନ୍ତୁ।",
