    "vitals.interpretation.measurementUnavailable.summary": "ଏଠାରେ ବ୍ୟାଖ୍ୟା ଦେଖିବାକୁ ଏକ ମାପ ଯୋଡ଼ନ୍ତୁ।",
    "vitals.interpretation.measurementUnavailable.details": "ଆପଣ ଏକ ରିଡିଂ ଲିପିବଦ୍ଧ କରିସାରିଲେ, JeevanLink ଏହାର ସାଧାରଣ ଅର୍ଥକୁ ସାରାଂଶ କରିବ — ରୋଗ ନିର୍ଣ୍ଣୟ ଭାବରେ ନୁହେଁ, ଏକ ପର୍ଯ୍ୟବେକ୍ଷଣ ଭାବରେ।",
    "vitals.interpretation.bp.low.title": "ସାଧାରଣଠାରୁ କମ୍",
    "vitals.interpretation.bp.low.details": "ଏହି ରିଡିଂ ସାଧାରଣ ପରିସର ତୁଳନାରେ କମ୍ ଅଟେ। ଯଦି ଆପଣଙ୍କୁ ମୁଣ୍ଡ ବୁଲାଇବା, ମୂର୍ଚ୍ଛା କିମ୍ବା ଅସ୍ୱସ୍ତି ଅନୁଭବ ହୁଏ, ଆପଣଙ୍କ କ୍ଲିନିସିଆନ୍‌ଙ୍କୁ ଯୋଗାଯୋଗ କରନ୍ତୁ।",
