    "vitals.interpretation.bp.typical.details": "ଏହି ରିଡିଂ ବୟସ୍କମାନଙ୍କ ପାଇଁ ସାଧାରଣତଃ ରିପୋର୍ଟ ହୋଇଥିବା ସୁସ୍ଥ ପରିସର ମଧ୍ୟରେ ପଡ଼େ।",
    "vitals.interpretation.bp.slight.title": "ସାମାନ୍ୟ ବୃଦ୍ଧି",
    "vitals.interpretation.bp.slight.details": "ଏହା ସାଧାରଣ ପରିସର ତୁଳନାରେ ସାମାନ୍ୟ ଅଧିକ। ଏହିପରି ମାଝେମାଝେ ରିଡିଂ ସାଧାରଣ, କିନ୍ତୁ ସମୟ ସହିତ ଟ୍ରାକ୍ କରିବା ଉଚିତ୍।",
    "vitals.interpretation.bp.elevated.title": "ବୃଦ୍ଧି ପାଇଛି",
    "vitals.interpretation.bp.elevated.details": "ଏହି ରିଡିଂ ସାଧାରଣଠାରୁ ଅଧିକ। ଆପଣଙ୍କ ପରବର୍ତ୍ତୀ କ୍ଲିନିସିଆନ୍ ଭ୍ରମଣରେ ଏହି ପ୍ରବୃତ୍ତିକୁ ଉଲ୍ଲେଖ କରିବାକୁ ବିଚାର କରନ୍ତୁ।",
    "vitals.interpretation.bp.high.title": "ଉଚ୍ଚ",
    "vitals.interpretation.bp.high.details": "ଏହି ରିଡିଂ ସାଧାରଣ ପରିସର ତୁଳନାରେ ଯଥେଷ୍ଟ ଅଧିକ। ଦୟାକରି ଏହାକୁ ଆପଣଙ୍କ କ୍ଲିନିସିଆନ୍ ସହିତ ସେୟାର କରନ୍ତୁ, ବିଶେଷତଃ ଯଦି ଏହା ପୁନରାବୃତ୍ତ ହୁଏ।",
    "vitals.interpretation.hr.low.title": "ସାଧାରଣଠାରୁ କମ୍",
    "vitals.interpretation.hr.low.details": "ଏହି ପରିସର ତୁଳନାରେ କମ୍ ବିଶ୍ରାମ ହୃଦୟ ସ୍ପନ୍ଦନ ହାର କେତେକ ଲୋକଙ୍କ ପାଇଁ ସାଧାରଣ ହୋଇପାରେ, ବିଶେଷତଃ ଯଦି ସକ୍ରିୟ କିମ୍ବା ଆଥଲେଟିକ୍ ହୁଅନ୍ତି, କିନ୍ତୁ ଅସ୍ୱସ୍ତି ଲାଗିଲେ ଉଲ୍ଲେଖ କରନ୍ତୁ।",
    "vitals.interpretation.hr.typical.title": "ସାଧାରଣ ପରିସର ମଧ୍ୟରେ",
    "vitals.interpretation.hr.typical.details": "ଏହି ବିଶ୍ରାମ ହୃଦୟ ସ୍ପନ୍ଦନ ହାର ବୟସ୍କମାନଙ୍କ ପାଇଁ ସାଧାରଣତଃ ରିପୋର୍ଟ ହୋଇଥିବା ସୁସ୍ଥ ପରିସର ମଧ୍ୟରେ ପଡ଼େ।",
    "vitals.interpretation.hr.high.title": "ସାଧାରଣଠାରୁ ଅଧିକ",
    "vitals.interpretation.hr.high.details": "ଏହା ସାଧାରଣ ବିଶ୍ରାମ ପରିସର ତୁଳନାରେ ଅଧିକ। ଯଦି ଏହା ଜାରି ରହେ କିମ୍ବା ଲକ୍ଷଣ ସହିତ ଆସେ, ଆପଣଙ୍କ କ୍ଲିନିସିଆନ୍ ସହିତ ଯାଞ୍ଚ କରନ୍ତୁ।",
    "vitals.interpretation.o2.reassuring.title": "ଆଶ୍ୱାସନାଦାୟକ",
