    "vitals.interpretation.o2.low.title": "ସାଧାରଣଠାରୁ କମ୍",
    "vitals.interpretation.o2.low.details": "ଏହି ରିଡିଂ ସାଧାରଣ ପରିସର ତୁଳନାରେ କମ୍ ଅଟେ। ଯଦି ଆପଣଙ୍କୁ ନିଶ୍ୱାସ ନେବାରେ ଅସୁବିଧା ହେଉଛି, ଦୟାକରି ଚିକିତ୍ସା ସହାୟତା ନିଅନ୍ତୁ।",
