    "vitals.interpretation.temp.high.title": "ଜ୍ୱର ପରିସର",
    "vitals.interpretation.temp.high.details": "ଏହି ରିଡିଂ ଜ୍ୱର ସୂଚାଏ। ବିଶ୍ରାମ, ତରଳ ପଦାର୍ଥ ଏବଂ ନିରୀକ୍ଷଣ ସାଧାରଣତଃ ପରାମର୍ଶ ଦିଆଯାଏ — ଯଦି ଏହା ଜାରି ରହେ କିମ୍ବା ଗମ୍ଭୀର ହୁଏ ତେବେ ଆପଣଙ୍କ କ୍ଲିନିସିଆନ୍‌ଙ୍କୁ ଯୋଗାଯୋଗ କରନ୍ତୁ।",
    "vitals.interpretation.temp.outside.title": "ସାଧାରଣ ପରିସର ବାହାରେ",
    "vitals.interpretation.temp.outside.details": "ଏହି ରିଡିଂ ସାଧାରଣତଃ ରିପୋର୍ଟ ହୋଇଥିବା ସାଧାରଣ ପରିସର ବାହାରେ ଅଛି। ପୁନର୍ବାର ମାପିବାକୁ ବିଚାର କରନ୍ତୁ, ଏବଂ ଯଦି ଏହା ଜାରି ରହେ ତେବେ ଆପଣଙ୍କ କ୍ଲିନିସିଆନ୍‌ଙ୍କୁ ଜଣାନ୍ତୁ।",
